using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptionLinkEffect", menuName = "Data/Battle/Effects/Enemy/CorruptionLink Effect")]
public class CorruptionLinkEffect : Effect
{
	private const string corruptedLinkWhileSentinelActiveID = "CorruptedLinkWhileSentinelActive";

	private const string corruptedSentinelID = "CorruptedSentinel";

	private const string corruptedAssistantID = "CorruptedAssistant_N";

	[Header("Corruption Link")]
	[SerializeField]
	private CorruptionSourceCorruptionLinkEffect effect;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private bool checkIfOtherSentinelWithSameEffect;

	public string CorruptedSentinelID => "CorruptedSentinel";

	public string CorruptedAssistantID => "CorruptedAssistant_N";

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedString = base.localizationManager.GetLocalizedString("CorruptedLinkWhileSentinelActive");
		string text = "Corrupted Sentinel";
		string text2 = "Corrupted Assembler";
		if (effectOwner != null)
		{
			if (GameScenesUtils.IsBattleScene() && (bool)effectOwner.GetComponent<CorruptedAnimalInitializer>())
			{
				CorruptedAnimalData corruptedAnimalData = effectOwner.GetComponent<CorruptedAnimalInitializer>().CorruptedAnimalData;
				text = ((!(corruptedAnimalData.CorruptedAnimalName == "CorruptedAssistant")) ? base.localizationManager.GetLocalizedString("CorruptedSentinel") : corruptedAnimalData.GetLocalizedName());
				text2 = currentCorruptedAnimals.GetCorruptionSource().GetComponent<CorruptedAnimalInitializer>().CorruptedAnimalData.GetLocalizedName();
			}
		}
		else
		{
			text = base.localizationManager.GetLocalizedString("CorruptedSentinel");
			text2 = base.localizationManager.GetLocalizedString("CorruptedAssembler_N");
		}
		if (amount == EffectsValues.NO_VALUE)
		{
			return Smart.Format(localizedString.Replace(" {2}", "").Replace("{2}", "").Replace("{3}", "{2}"), text, text2, effect.Effect.GetEffectName());
		}
		return Smart.Format(localizedString, text, text2, amount, effect.Effect.GetEffectName());
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		currentCorruptedAnimals.GetCorruptionSource().GetComponent<UnitEffects>().AddEffect(effect, effectAmount);
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		Debug.Log("CORRUPTION LINK: " + effect.name + " " + effectAmount);
		if (checkIfOtherSentinelWithSameEffect)
		{
			List<GameObject> corruptedAnimalsNotCorruptionSource = currentCorruptedAnimals.GetCorruptedAnimalsNotCorruptionSource();
			for (int i = 0; i < corruptedAnimalsNotCorruptionSource.Count; i++)
			{
				if (!(corruptedAnimalsNotCorruptionSource[i] == effectOwner) && corruptedAnimalsNotCorruptionSource[i].GetComponent<CorruptedAnimalEffects>().IsEffectActive(this, activateFeedback: false))
				{
					return;
				}
			}
		}
		if (base.HideEffectValue)
		{
			Debug.Log("CORRUPTION LINK HIDE EFFECT VALUE: " + effect.name + " " + effectAmount);
			GameObject corruptionSource = currentCorruptedAnimals.GetCorruptionSource();
			if (corruptionSource != null)
			{
				corruptionSource.GetComponent<UnitEffects>().RemoveEffect(effect);
			}
		}
		else
		{
			GameObject corruptionSource2 = currentCorruptedAnimals.GetCorruptionSource();
			if (corruptionSource2 != null)
			{
				corruptionSource2.GetComponent<UnitEffects>().DecreaseEffect(effect, effectAmount);
			}
		}
	}
}
